INSERT INTO `jpath_kanji` (`code`, `level`, `character`, `sort_order`, `han_viet`, `han_viet_alt_json`, `meanings_vi`, `readings_on_json`, `readings_kun_json`, `level_readings_json`, `level_reading_source`, `stroke_count`, `radical_number`, `radical_name_vi`, `frequency`, `mnemonic_vi`, `dictionary_kanji_id`, `status`, `authored`, `seed_version`) VALUES
('JK-4E38', 'N2', '丸', 2, 'Hoàn', '[]', 'tròn; viên thuốc', '["ガン"]', '["まる","まる.める","まる.い"]', '["まる","まる.い"]', 'LEVEL_WORDS', 3, 3, 'chủ', NULL, 'Một viên thuốc nhỏ có cái chấm trên đầu lăn tròn xoe: HOÀN (丸) là viên tròn, nghe như "hoàn" thuốc.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-4E71', 'N2', '乱', 92, 'Loạn', '["Làn","Loàn"]', 'bạo loạn; chiến tranh; rối loạn', '["ラン","ロン"]', '["みだ.れる","みだ.る","みだ.す","みだ","おさ.める","わた.る"]', '["らん","みだ.れる","みだ.す"]', 'LEVEL_WORDS', 7, 5, 'ất', NULL, 'Sợi chỉ (幺) rối bời, bị cái móc (乚) kéo lệch từ hai phía: mọi thứ thành một mớ LOẠN.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-4E7E', 'N2', '乾', 164, 'Kiền', '["Can"]', 'khô; uống cạn; trời', '["カン","ケン"]', '["かわ.く","かわ.かす","ほ.す","ひ.る","いぬい"]', '["かん","かわ.く","かわ.かす"]', 'LEVEL_WORDS', 11, 5, 'ất', NULL, 'Mặt trời mọc từ sớm 倝 rọi vào cây cối, khiến mọi thứ khô ráo: KIỀN (乾) là khô, đồng thời là quẻ trời.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-4E86', 'N2', '了', 1, 'Liễu', '[]', 'hoàn thành; kết thúc', '["リョウ"]', '[]', '["りょう"]', 'LEVEL_WORDS', 2, 6, 'quyết', NULL, 'Nét móc cuối cùng kéo xuống như người đã gạch xong dòng chót, mọi việc LIỄU kết nên không còn gì phải thêm.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-4ECF', 'N2', '仏', 70, 'Phật', '[]', 'phật; người chết; pháp', '["ブツ","フツ"]', '["ほとけ"]', '["ほとけ"]', 'LEVEL_WORDS', 4, 9, 'nhân', NULL, 'Người (亻) ngồi tĩnh lặng và bao quanh là ngôi nhà nhỏ (厶): bậc tu hành, PHẬT.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-4EE4', 'N2', '令', 39, 'Lệnh', '["Linh"]', 'mệnh lệnh; luật lệ; chỉ thị', '["レイ"]', '[]', '["れい"]', 'LEVEL_WORDS', 5, 9, 'nhân', NULL, 'Dưới cái mái nhà (人) có người quỳ (卩) nghe lệnh của cấp trên: LỆNH là mệnh lệnh, chỉ thị.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-4EF2', 'N2', '仲', 32, 'Trọng', '[]', 'người trung gian; mối quan hệ', '["チュウ"]', '["なか"]', '["ちゅう","なか"]', 'LEVEL_WORDS', 6, 9, 'nhân', NULL, 'Người (亻) đứng giữa (中) hai bên làm trung gian hòa giải; TRỌNG ở đây là người ở giữa, mối quan hệ giữa hai người.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-4F38', 'N2', '伸', 217, 'Thân', '[]', 'mở rộng; kéo dài', '["シン"]', '["の.びる","の.ばす","の.べる","の.す"]', '["の.びる","の.ばす"]', 'LEVEL_WORDS', 7, 9, 'nhân', NULL, 'Người 亻 vươn người thẳng, kéo giãn một đường dọc 申 ra: THÂN (伸) là duỗi, kéo dài.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-4F4E', 'N2', '低', 33, 'Đê', '[]', 'thấp hơn; ngắn; khiêm tốn', '["テイ"]', '["ひく.い","ひく.める","ひく.まる"]', '["てい","ひく.い"]', 'LEVEL_WORDS', 7, 9, 'nhân', NULL, 'Người (亻) cúi gập xuống sát gốc (氏) như người khom mình chào, thấp hơn người khác: ĐÊ là thấp.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-4F9D', 'N2', '依', 222, 'Y', '["Ỷ"]', 'dựa vào; phụ thuộc; do đó', '["イ","エ"]', '["よ.る"]', '["い"]', 'LEVEL_WORDS', 8, 9, 'nhân', NULL, 'Người 亻 mặc áo 衣 che chở nên dựa vào áo ấy mà sống: Y (依) là dựa vào, nương tựa.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-500B', 'N2', '個', 96, 'Cá', '[]', 'cá nhân; đơn vị đếm đồ vật', '["コ","カ"]', '[]', '["こ","か"]', 'LEVEL_WORDS', 10, 9, 'nhân', NULL, 'Người (亻) đứng vững như cái bàn cứng (固) chắc nịch, mỗi người là một cá thể riêng: CÁ nhân, một cái.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-500D', 'N2', '倍', 41, 'Bội', '[]', 'gấp đôi; hai lần; lần', '["バイ"]', '[]', '["ばい"]', 'LEVEL_WORDS', 10, 9, 'nhân', NULL, 'Người (亻) đứng bên cạnh một người nữa (咅) nên thành hai người, gấp đôi: BỘI là gấp đôi, gấp nhiều lần.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-505C', 'N2', '停', 113, 'Đình', '[]', 'dừng lại; dừng', '["テイ"]', '["と.める","と.まる"]', '["てい"]', 'LEVEL_WORDS', 11, 9, 'nhân', NULL, 'Người (亻) đến nhà cao (亭) rồi ngồi nghỉ chân: ĐÌNH là dừng lại, như "đình chỉ", "đình chiến".', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-50BE', 'N2', '傾', 233, 'Khuynh', '[]', 'nghiêng; xu hướng; suy tàn', '["ケイ"]', '["かたむ.く","かたむ.ける","かたぶ.く","かた.げる","かし.げる"]', '["けい","かたむ.く","かたむ.ける"]', 'LEVEL_WORDS', 13, 9, 'nhân', NULL, 'Người 亻 nghiêng đầu 頃 về một bên, thân mình lệch đi: KHUYNH (傾) là nghiêng, khuynh hướng.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-50CF', 'N2', '像', 53, 'Tượng', '[]', 'tượng; bức tranh; hình ảnh', '["ゾウ"]', '[]', '["ぞう"]', 'LEVEL_WORDS', 14, 9, 'nhân', NULL, 'Người (亻) có hình dáng giống con voi (象) khi khắc thành tượng: TƯỢNG là bức tượng, hình ảnh.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-5104', 'N2', '億', 49, 'Ức', '[]', 'trăm triệu', '["オク"]', '[]', '["おく"]', 'LEVEL_WORDS', 15, 9, 'nhân', NULL, 'Người (亻) nhìn thấy ý (意) niệm về một con số quá lớn, đến trăm triệu: ỨC là số lớn.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-5146', 'N2', '兆', 230, 'Triệu', '[]', 'điềm báo; 10**12; nghìn tỷ', '["チョウ"]', '["きざ.す","きざ.し"]', '["ちょう","きざ.し"]', 'DICTIONARY_WORDS', 6, 10, 'nhân đi', NULL, 'Vết nứt trên mai rùa chia thành hai bên, báo trước điều sắp tới: TRIỆU (兆) là điềm báo, triệu chứng.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-5150', 'N2', '児', 157, 'Nhi', '[]', 'trẻ sơ sinh; trẻ em; đứa trẻ', '["ジ","ニ","ゲイ"]', '["こ","-こ","-っこ"]', '["じ","に"]', 'LEVEL_WORDS', 7, 10, 'nhân đi', NULL, 'Đứa bé với cái đầu to, thóp chưa kín (臼) và hai chân bé xíu 儿: NHI (児) là trẻ con, em bé.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-515A', 'N2', '党', 191, 'Đảng', '[]', 'đảng; phe phái; bè phái', '["トウ"]', '["なかま","むら"]', '["とう"]', 'LEVEL_WORDS', 10, 10, 'nhân đi', NULL, 'Người anh 兄 đứng dưới chiếc mũ cao nhọn, cả nhóm cùng chung chí hướng: ĐẢNG (党) là đảng phái, phe nhóm.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-5175', 'N2', '兵', 76, 'Binh', '[]', 'lính; binh nhì; quân đội', '["ヘイ","ヒョウ"]', '["つわもの"]', '["へい"]', 'LEVEL_WORDS', 7, 12, 'bát', NULL, 'Hai tay vác cây rìu (斤) bên trên: người lính cầm vũ khí, BINH là binh lính.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-518D', 'N2', '再', 148, 'Tái', '[]', 'lại; hai lần; lần thứ hai', '["サイ","サ"]', '["ふたた.び"]', '["さい","さ","ふたた.び"]', 'LEVEL_WORDS', 6, 13, 'quynh', NULL, 'Cái hộp xếp thêm một tầng, rồi lại thêm một tầng nữa: lại một lần nữa là TÁI (再), như \'tái bản\', \'tái xuất\'.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-51CD', 'N2', '凍', 158, 'Đống', '[]', 'đông lạnh; đông cứng; làm lạnh', '["トウ"]', '["こお.る","こご.える","こご.る","い.てる","し.みる"]', '["とう","こお.る","こご.える"]', 'LEVEL_WORDS', 10, 15, 'băng', NULL, 'Băng 冫 phủ lên đồ vật ở phương đông 東 trời lạnh buốt: ĐỐNG (凍) là đóng băng, đông cứng.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-520A', 'N2', '刊', 232, 'Khan', '["San"]', 'xuất bản; khắc', '["カン"]', '[]', '["かん"]', 'LEVEL_WORDS', 5, 18, 'đao', NULL, 'Dao 刂 khắc lên bản gỗ mốc can 干 để in ra báo: KHAN (刊) là xuất bản, ấn hành.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-5237', 'N2', '刷', 255, 'Xoát', '["Loát"]', 'in ấn', '["サツ"]', '["す.る","-ず.り","-ずり","は.く"]', '["さつ","す.る"]', 'LEVEL_WORDS', 8, 18, 'đao', NULL, 'Bên trái là bản khắc, bên phải là con dao (刂) cạo sạch để in từng tờ: XOÁT, in ấn.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-5238', 'N2', '券', 162, 'Khoán', '[]', 'vé', '["ケン"]', '[]', '["けん"]', 'LEVEL_WORDS', 8, 18, 'đao', NULL, 'Tờ giấy gấp lại, bên dưới có con dao 刀 cắt dọc ra phần vé: KHOÁN (券) là tấm vé, phiếu.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-5247', 'N2', '則', 116, 'Tắc', '[]', 'quy tắc; luật; theo', '["ソク"]', '["のっと.る","のり","すなわち"]', '["そく"]', 'LEVEL_WORDS', 9, 18, 'đao', NULL, 'Đồ quý (貝) bên cạnh con dao (刂): người ta lập ra quy tắc bằng cách phân chia đồ quý rõ ràng, TẮC là quy tắc.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-526F', 'N2', '副', 111, 'Phó', '[]', 'phó-; trợ lý; phụ tá', '["フク"]', '[]', '["ふく"]', 'LEVEL_WORDS', 11, 18, 'đao', NULL, 'Dao (刂) cắt đôi cái bình đầy (畐), một nửa làm phó, một nửa làm chính: PHÓ là người phụ, hạng hai.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-5287', 'N2', '劇', 205, 'Kịch', '[]', 'kịch; vở kịch', '["ゲキ"]', '[]', '["げき"]', 'LEVEL_WORDS', 15, 18, 'đao', NULL, 'Con hổ 虍 và con lợn 豕 diễn đấu nhau, rồi dùng dao 刂 giả đâm: KỊCH (劇) là vở kịch, trò diễn mạnh.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-52B9', 'N2', '効', 138, 'Hiệu', '[]', 'công hiệu; hiệu quả; lợi ích', '["コウ"]', '["き.く","ききめ","なら.う"]', '["こう","き.く"]', 'LEVEL_WORDS', 8, 19, 'lực', NULL, 'Người ta giao 交 việc rồi dồn sức 力 vào làm: có HIỆU (効) quả, thuốc hay việc gì đó thấy tác dụng ngay.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-52C7', 'N2', '勇', 66, 'Dũng', '[]', 'dũng cảm; phấn chấn', '["ユウ"]', '["いさ.む"]', '["ゆう","いさ.む"]', 'LEVEL_WORDS', 9, 19, 'lực', NULL, 'Tiếng hô vang trên con đường (マ + 男) rồi dồn sức (力) lao lên: DŨNG là người gan dạ không sợ.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-52DF', 'N2', '募', 224, 'Mộ', '[]', 'tuyển dụng; chiến dịch; thu thập (đóng góp)', '["ボ"]', '["つの.る"]', '["ぼ"]', 'LEVEL_WORDS', 12, 19, 'lực', NULL, 'Mặt trời lặn 莫 phía sau, người ta dồn sức 力 kêu gọi thêm người: MỘ (募) là tuyển mộ, quyên góp.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-52E2', 'N2', '勢', 108, 'Thế', '[]', 'lực lượng; sức mạnh', '["セイ","ゼイ"]', '["いきお.い","はずみ"]', '["せい","ぜい","いきお.い"]', 'LEVEL_WORDS', 13, 19, 'lực', NULL, 'Đất và cây (坴) cùng với tròn đầy sức (力), gom tròn thành một thế lực: THẾ là khí thế, quyền thế.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-5305', 'N2', '包', 245, 'Bao', '[]', 'gói; đóng gói; che phủ', '["ホウ"]', '["つつ.む","くる.む"]', '["ほう","つつ.む","くる.む"]', 'LEVEL_WORDS', 5, 20, 'bao', NULL, 'Bên ngoài là bàn tay ôm vòng (勹) quấn lấy phần bên trong (巳) như em bé được tã bọc kín: BAO bọc, gói lại.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-5339', 'N2', '匹', 260, 'Thất', '[]', 'bằng nhau; đầu; đơn vị đếm động vật nhỏ', '["ヒツ"]', '["ひき"]', '["ひつ"]', 'LEVEL_WORDS', 4, 23, 'hệ', NULL, 'Cái hộp mở (匚) đựng con vật nhỏ nằm ngang hàng nhau, mỗi con một con: THẤT, đếm từng con vật nhỏ.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-533A', 'N2', '区', 64, 'Âu', '["Khu"]', 'quận; khu vực', '["ク","オウ","コウ"]', '[]', '["く"]', 'LEVEL_WORDS', 4, 23, 'hệ', NULL, 'Cái hộp (匚) chứa những vật nhỏ (ㄨ) chia ra từng ô riêng; mỗi ô là một khu vực, một quận, ÂU.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-5354', 'N2', '協', 54, 'Hiệp', '[]', 'hợp tác', '["キョウ"]', '[]', '["きょう"]', 'LEVEL_WORDS', 8, 24, 'thập', NULL, 'Mười (十) người cùng góp sức (力 ba lần) kéo một việc lớn: HIỆP lực là hợp tác với nhau.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-5360', 'N2', '占', 149, 'Chiêm', '["Chiếm"]', 'chiếm; dự đoán; chiếm giữ', '["セン"]', '["し.める","うらな.う"]', '["し.める","うらな.う"]', 'LEVEL_WORDS', 5, 25, 'bốc', NULL, 'Bói quẻ: que gạch đứng 卜 chỉ vào cái miệng 口 hỏi, rồi chiếm lấy vị trí đó: CHIÊM (占) là bói toán, chiếm giữ.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-539A', 'N2', '厚', 98, 'Hậu', '[]', 'dày; nặng; giàu', '["コウ"]', '["あつ.い","あか"]', '["こう","あつ.い"]', 'LEVEL_WORDS', 9, 27, 'hán', NULL, 'Dưới vách (厂) là mặt trời (日) và đứa con (子): lớp đất chồng lên nhau dày thêm, HẬU là dày.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-53CC', 'N2', '双', 248, 'Song', '[]', 'đôi; cặp', '["ソウ"]', '["ふた","たぐい","ならぶ","ふたつ"]', '["そう","ふた"]', 'LEVEL_WORDS', 4, 29, 'hựu', NULL, 'Hai chữ HỰU (又) là hai bàn tay đặt cạnh nhau thành một cặp: đôi bàn tay thành SONG, một đôi.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-53EB', 'N2', '叫', 261, 'Khiếu', '[]', 'kêu la', '["キョウ"]', '["さけ.ぶ"]', '["さけ.ぶ"]', 'LEVEL_WORDS', 6, 30, 'khẩu', NULL, 'Cái miệng (口) bên cạnh chữ CƯ (丩) quấn vào nhau như cổ họng thắt lại, hét lên thật lớn: KHIẾU, kêu la.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
('JK-53EF', 'N2', '可', 302, 'Khả', '["Khắc"]', 'có thể; đạt; chấp thuận', '["カ","コク"]', '["-べ.き","-べ.し"]', '["か"]', 'LEVEL_WORDS', 5, 30, 'khẩu', NULL, 'Cái miệng (口) bên cạnh cái móc (丁) đặt dưới mái ngang: nói được vậy tức là KHẢ, có thể, được phép.', NULL, 'AI_CHECKED', 1, '7f471837a68d'),
